        Body.Children.Add(Ui.Card(Ui.Stack(Ui.Text("Kaynak kullanımı",17,null,true),Ui.Space(),Ui.Row(Ui.Stack(Ui.Caption("YENİLEMEDE MAÇ SAYISI"),count),Ui.Stack(Ui.Caption("CANLI OKUMA ARALIĞI · SANİYE"),poll),Ui.Stack(Ui.Caption("VARSAYILAN SUNUCU"),region)),economy,Ui.Button("Tercihleri kaydet",()=>{store.Preferences.MatchCount=(int)(count.SelectedItem??20);store.Preferences.PollSeconds=(int)(poll.SelectedItem??5);store.Preferences.Economy=economy.IsChecked==true;store.Preferences.Platform=(region.SelectedItem as Region??Region.All[0]).Platform;RegionBox.SelectedItem=region.SelectedItem;store.Save();liveTimer.Interval=TimeSpan.FromSeconds(WindowState==WindowState.Minimized&&store.Preferences.Economy?15:store.Preferences.PollSeconds);SetNotice("Tercihler kaydedildi.");}),Ui.Space(),Ui.Text("Boşta Riot sorgusu, reklam, analiz takibi veya otomatik güncelleyici çalışmaz. Canlı takip uygulama açıkken otomatik çalışır; maç başlayınca Canlı maç sekmesi açılır. Kontrol yalnızca bu bilgisayardaki oyun API’sine yapılır. Sunuculu sürüm bilgisayarında ayrı arka servis başlatmaz. API ve maç önbelleği 128 MB ile sınırlanır; kayıtlı dizilimler ve arkadaşların ayrı saklanır.",12,Ui.Muted))));
        Body.Children.Add(Ui.Card(Ui.Stack(Ui.Text("Veri ve tanılama",17,null,true),Ui.Space(),Ui.Text($"Statik veri: Data Dragon {data.Version}\nAPI önbelleği: {store.CacheBytes/1024.0/1024:0.0} MB\nKayıt klasörü: {store.Root}",12,Ui.Muted),Ui.Space(),Ui.Row(Ui.Button("Statik veriyi güncelle",async()=>await Run("Riot eşya, şampiyon ve rün verileri güncelleniyor…",async ct=>{await data.Refresh(ct);Render();SetNotice("Data Dragon "+data.Version+" verileri güncellendi.");})),Ui.Button("Önbelleği temizle",()=>{if(busy){SetNotice("Önce süren işlemi tamamla veya iptal et.");return;}store.ClearCache();matches=[];Render();SetNotice("API/maç önbelleği temizlendi. Arkadaşlar, ayarlar ve dizilimler korundu.");}),Ui.Button("Riot servis durumu",async()=>await Run("Servis durumu okunuyor…",async ct=>{var r=await api.Status(RegionBox.SelectedItem as Region??Region.All[0],ct);SetNotice($"{r.S("name")} · {r.A("maintenances").Count()} bakım · {r.A("incidents").Count()} olay. "+string.Join(" · ",r.A("incidents").SelectMany(x=>x.A("titles")).Select(x=>x.S("content"))));}))),Ui.Space(),Ui.Button(demo!=null?"Örnek modu kapat":"Örnek görünümü aç",()=>{ResetLiveSession();spectator=null;demo=demo==null?new Demo():null;UpdatePlayers();SetNotice(demo!=null?"ÖRNEK MOD · Tüm oyuncu, maç ve canlı veriler kurgusaldır.":"Gerçek veri modu · Riot ID ile oyuncu ara.");Navigate("overview");} ))));
